"""Manually authored recognition cards for both full English texts of the Odyssey.

Butler's original renders the gods and the hero with their Roman names
(Ulysses, Jove, Minerva, Neptune); the modern edition restores the Greek
(Odysseus, Zeus, Athena, Poseidon). Every affected entity carries both forms as
aliases, so one card serves both editions.

Scope: named people, gods, personified powers, named animals and named peoples.
Places, rivers, mountains, islands, ships, stars and the adjectival forms of
place names are not cast and are not bound.
"""
import json
from pathlib import Path
entities=[]
def add(id,name,body,aliases='',category='supporting',kind='person',snapshots=None,roleAfter=None):
 e=dict(id=id,name=name,body=body,aliases=aliases.split('|') if aliases else [],category=category,kind=kind,subtitle='',snapshots=snapshots or [])
 if roleAfter:e['roleAfter']=roleAfter
 entities.append(e)

