# Later identity clarifications, each released at the end of the paragraph that
# establishes it in the source. Nothing here anticipates an outcome.
SNAPSHOTS={
 'telemachus':[([16,22],'Odysseus’s son. He has now met his father, who revealed himself to him at the swineherd’s hut.')],
 'eumaeus':[([15,33],'Odysseus’s swineherd, loyal to the absent master. He was born a king’s son on the island of Syra, the child of Ctesius son of Ormenus.')],
 'irus':[([18,10],'The town beggar of Ithaca, really named Arnaeus, who challenged the stranger at the door and was beaten.')],
 'theoclymenus':[([20,30],'The seer Telemachus brought home from Pylos, of the house of Melampus; he reads the darkness that falls over the suitors at their meal.')],
}
for e in entities:
 for after,body in SNAPSHOTS.get(e['id'],[]):e['snapshots'].append(dict(after=after,body=body))

